/* The tables of M12 · Timetable. */

/** The clock times of a school day. Summer, winter, Ramadan and Friday each have their own. */
export const bellSchedules = defineTable(
  'bell_schedules',
  { module: 'M12', scope: 'branch', member: { read: { status: 'active' } } },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** `Summer`, `Ramadan`, `Friday` */
    name: text().notNull(),
    shiftId: uuid()
      .references((): AnyPgColumn => shifts.id)
      .notNull(),
    validFrom: dateStr().notNull(),
    /** empty means until replaced */
    validTo: dateStr(),
    /** subset of `mon`…`sun` this schedule applies to */
    weekdays: text().array().notNull(),
    /** number of teaching periods in the day */
    lessonCount: integer().notNull(),
    status: enumText(bellScheduleStatuses).notNull().default('draft'),
  },
  (t) => [
    check('bell_schedules_valid_to_from', sql`${t.validTo} >= ${t.validFrom}`),
    check(
      'bell_schedules_weekdays_days',
      sql`cardinality(${t.weekdays}) >= 1 and ${t.weekdays} <@ array['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']`,
    ),
    positive('bell_schedules', t.lessonCount),
    uniqueIndex('bell_schedules_branch_name_uq').on(t.branchId, t.name).where(live(t)),
  ],
);

export const bellPeriods = defineTable(
  'bell_periods',
  { module: 'M12', scope: 'branch', member: 'read' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    bellScheduleId: uuid()
      .references((): AnyPgColumn => bellSchedules.id)
      .notNull(),
    /** order in the day */
    sequence: integer().notNull(),
    kind: enumText(bellPeriodKinds).notNull(),
    /** 1, 2, 3… for `lesson` rows only */
    lessonNo: integer(),
    /** `Period 1`, `Break` */
    name: text().notNull(),
    startTime: timeStr().notNull(),
    endTime: timeStr().notNull(),
  },
  (t) => [
    positive('bell_periods', t.sequence),
    positive('bell_periods', t.lessonNo),
    check('bell_periods_lesson_no_kind', sql`(${t.kind} = 'lesson') = (${t.lessonNo} is not null)`),
    check('bell_periods_end_time_after', sql`${t.endTime} > ${t.startTime}`),
    uniqueIndex('bell_periods_bell_schedule_sequence_uq')
      .on(t.bellScheduleId, t.sequence)
      .where(live(t)),
    uniqueIndex('bell_periods_bell_schedule_lesson_no_uq')
      .on(t.bellScheduleId, t.lessonNo)
      .where(sql`${t.deletedAt} is null and ${t.lessonNo} is not null`),
  ],
);

/** A weekly plan for all sections of a shift. */
export const timetables = defineTable(
  'timetables',
  { module: 'M12', scope: 'branch', member: { read: { status: 'published' } } },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    academicYearId: uuid()
      .references((): AnyPgColumn => academicYears.id)
      .notNull(),
    shiftId: uuid()
      .references((): AnyPgColumn => shifts.id)
      .notNull(),
    name: text().notNull(),
    effectiveFrom: dateStr().notNull(),
    effectiveTo: dateStr(),
    status: enumText(timetableStatuses).notNull().default('draft'),
    publishedAt: timestamptz(),
    publishedBy: uuid().references((): AnyPgColumn => profiles.id),
    copiedFromId: uuid().references((): AnyPgColumn => timetables.id),
  },
  (t) => [check('timetables_effective_to_from', sql`${t.effectiveTo} >= ${t.effectiveFrom}`)],
);

export const timetableEntries = defineTable(
  'timetable_entries',
  { module: 'M12', scope: 'branch', member: 'read' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    timetableId: uuid()
      .references((): AnyPgColumn => timetables.id)
      .notNull(),
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    weekday: enumText(timetableEntryWeekdays).notNull(),
    lessonNo: integer().notNull(),
    sectionSubjectId: uuid()
      .references((): AnyPgColumn => sectionSubjects.id)
      .notNull(),
    /** defaults to the subject's teacher */
    teacherId: uuid().references((): AnyPgColumn => staff.id),
    /** defaults to the section's room */
    roomId: uuid().references((): AnyPgColumn => rooms.id),
    note: text(),
  },
  (t) => [
    positive('timetable_entries', t.lessonNo),
    uniqueIndex('timetable_entries_timetable_section_weekday_lesson_no_uq')
      .on(t.timetableId, t.sectionId, t.weekday, t.lessonNo)
      .where(live(t)),
    uniqueIndex('timetable_entries_timetable_teacher_weekday_lesson_no_uq')
      .on(t.timetableId, t.teacherId, t.weekday, t.lessonNo)
      .where(sql`${t.deletedAt} is null and ${t.teacherId} is not null`),
    uniqueIndex('timetable_entries_timetable_room_weekday_lesson_no_uq')
      .on(t.timetableId, t.roomId, t.weekday, t.lessonNo)
      .where(sql`${t.deletedAt} is null and ${t.roomId} is not null`),
  ],
);

