/** One period on one date covered by someone else, or left free. */
export const substitutions = defineTable(
  'substitutions',
  { module: 'M12', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    substitutionDate: dateStr().notNull(),
    timetableEntryId: uuid()
      .references((): AnyPgColumn => timetableEntries.id)
      .notNull(),
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    lessonNo: integer().notNull(),
    absentTeacherId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    /** empty means a free period */
    substituteTeacherId: uuid().references((): AnyPgColumn => staff.id),
    reason: enumText(substitutionReasons).notNull(),
    leaveRequestId: uuid().references((): AnyPgColumn => leaveRequests.id),
    status: enumText(substitutionStatuses).notNull().default('planned'),
    note: text(),
  },
  (t) => [
    positive('substitutions', t.lessonNo),
    uniqueIndex('substitutions_substitution_date_timetable_entry_uq')
      .on(t.substitutionDate, t.timetableEntryId)
      .where(live(t)),
    uniqueIndex('substitutions_substitution_date_substitute_teacher_lesson_no_uq')
      .on(t.substitutionDate, t.substituteTeacherId, t.lessonNo)
      .where(sql`${t.deletedAt} is null and ${t.substituteTeacherId} is not null`),
  ],
);
